import{_ as e,o as a,c as l,a5 as s}from"./chunks/framework.Bkm3ODFN.js";const n="/assets/overview-topology.CyV8rHeC.svg",b=JSON.parse('{"title":"💼 AIoT 行业落地案例全景","description":"","frontmatter":{},"headers":[],"relativePath":"cases/overview.md","filePath":"cases/overview.md","lastUpdated":null}'),r={name:"cases/overview.md"};function i(d,t,o,p,g,x){return a(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="💼-aiot-行业落地案例全景" tabindex="-1">💼 AIoT 行业落地案例全景 <a class="header-anchor" href="#💼-aiot-行业落地案例全景" aria-label="Permalink to &quot;💼 AIoT 行业落地案例全景&quot;">​</a></h1><p>从设备孤岛到“声光电像智”全面协同，看 MzMedia 如何赋能千行百业实现低成本、高可靠的数字化转型与智能化运维。</p><hr><h2 id="🏗️-方案全景架构拓扑" tabindex="-1">🏗️ 方案全景架构拓扑 <a class="header-anchor" href="#🏗️-方案全景架构拓扑" aria-label="Permalink to &quot;🏗️ 方案全景架构拓扑&quot;">​</a></h2><p>MzMedia 将 <strong>13+ 种工业物联网协议网关</strong>、<strong>GB/T 28181 安防流媒体中枢</strong> 与 <strong>Spring AI 智能中枢</strong> 紧密缝合，构建了覆盖物理感知、边缘流媒体、核心规则引擎与企业业务协同的全栈闭环体系：</p><div style="text-align:center;margin:24px 0;"><img src="'+n+`" alt="MzMedia AIoT 全场景端到端闭环协同拓扑" style="border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.3);max-width:100%;border:1px solid var(--vp-c-border);"><p style="font-size:13px;color:var(--vp-c-text-3);margin-top:8px;">图 1：MzMedia 企业级 AIoT 全场景物理感知、边缘流媒体、规则时序与业务闭环协同总拓扑</p></div><hr><h2 id="🌐-行业解决方案矩阵对照" tabindex="-1">🌐 行业解决方案矩阵对照 <a class="header-anchor" href="#🌐-行业解决方案矩阵对照" aria-label="Permalink to &quot;🌐 行业解决方案矩阵对照&quot;">​</a></h2><p>传统的物联网方案往往“只看数据不看实况”，安防视频系统“事后查证无法主动预警”，业务系统（MES/PMS/WMS）与底层工控硬件更是互为烟囱。MzMedia 在以下行业深水区形成了标准化的落地落盘模板：</p><table tabindex="0"><thead><tr><th style="text-align:left;">行业场景</th><th style="text-align:left;">客户典型痛点</th><th style="text-align:left;">MzMedia 破局方案</th><th style="text-align:left;">核心协同技术</th><th style="text-align:left;">标杆客户实测 ROI</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/cases/video-linkage.html"><strong>📹 视频深度联动</strong></a></td><td style="text-align:left;">传感器告警无画面，安保翻查录像耗时 15 分钟，错过黄金处置时机</td><td style="text-align:left;">传感器超限 1.8 秒内驱动球机预置位旋转（0x81），自动切片录像与 AI 视觉复核</td><td style="text-align:left;">TCA 规则引擎 + GB28181 SIP + WebRTC 低延时直播 + 多模态视觉大模型</td><td style="text-align:left;">故障实况响应时间从 <strong>15 分钟降至 1.8 秒</strong>，误报复核人工减少 85%</td></tr><tr><td style="text-align:left;"><a href="/cases/industrial.html"><strong>🏭 工业预测性维护</strong></a></td><td style="text-align:left;">机床与旋转机械非计划突发停机，损失高昂；人工巡检难以及时发现早期隐患</td><td style="text-align:left;">Modbus 高频采集振动/温升/电流，TDengine 列式高压缩时序存储，Spring AI RAG 诊断基线偏离</td><td style="text-align:left;">Modbus TCP + TDengine 3.0 + Spring AI MCP + MES 闭环工单 + WMS 备件预占</td><td style="text-align:left;">突发意外停机减少 <strong>62%</strong>，MTTR 从 6.5h 降至 1.8h，单产线年挽损 40+ 万元</td></tr><tr><td style="text-align:left;"><a href="/cases/security.html"><strong>🛡️ 智慧园区智能安防</strong></a></td><td style="text-align:left;">周界防范误报频发（风吹草动小动物），安保疲于奔命；夜间盲区多、取证难</td><td style="text-align:left;">脉冲电子围栏触碰瞬间联动 4K 球机预置位追踪，边缘视觉检测过滤干扰，反向声光震慑驱离</td><td style="text-align:left;">脉冲围栏 + GB28181 PTZ + YOLO 边缘视觉 + Modbus 爆闪警号反控</td><td style="text-align:left;">夜间误报率降至 <strong>1.5%</strong> 以下，真实入侵拦截率 100%，安保人力成本缩减 40%</td></tr><tr><td style="text-align:left;"><a href="/cases/agriculture.html"><strong>🌱 现代设施农业</strong></a></td><td style="text-align:left;">靠天吃饭、凭经验浇水施肥；温湿度剧变导致作物病害爆发，优质果品率低</td><td style="text-align:left;">温室温湿度、土壤水肥四合一多参数物联采集，自适应闭环驱动天窗/风机，AI 巡航识别早期病斑</td><td style="text-align:left;">LoRaWAN / Modbus + 农业 TSL + 自适应水肥环控 + 云台多预置位视觉巡检</td><td style="text-align:left;">节水 32%、节肥 25%，早期病虫害发现提前 3~5 天，一人可轻松统筹 20 栋大棚</td></tr><tr><td style="text-align:left;"><a href="/cases/education.html"><strong>🎓 数字化教育与实验室</strong></a></td><td style="text-align:left;">高校危化品防爆柜泄漏隐患大；实训违章着装难监管；大功率仪器忘关引发火警</td><td style="text-align:left;">防爆柜 VOC 与温湿度 7×24h 盯防，门禁联动球机 AI 识别实验服/护目镜，课表联动安全断电</td><td style="text-align:left;">VOC 传感器 + GB28181 预置位抓拍 + AI 视觉合规审计 + 智能微断空开</td><td style="text-align:left;">违规操作率下降 <strong>95%</strong>，危化品泄漏隐患秒级自愈排风，教学用电能耗削减 26%</td></tr><tr><td style="text-align:left;"><a href="/cases/energy-carbon.html"><strong>⚡ 智慧能源与低碳建筑</strong></a></td><td style="text-align:left;">需量超标罚款高，中央空调能耗过大，光伏消纳不足，峰谷套利缺乏动态策略</td><td style="text-align:left;">毫秒级采集电力仪表与储能状态，根据分时电价智能调度充放电，空调温度动态柔性调优</td><td style="text-align:left;">Modbus RTU/TCP + BMS/PCS 变流器 + 需量越限预测 + 柔性负荷控制</td><td style="text-align:left;">综合用电成本降低 <strong>19.4%</strong>，光伏消纳率提升至 99.2%，杜绝超需量违约金</td></tr></tbody></table><hr><h2 id="🛠️-标准化工程落地实施-4-步法" tabindex="-1">🛠️ 标准化工程落地实施 4 步法 <a class="header-anchor" href="#🛠️-标准化工程落地实施-4-步法" aria-label="Permalink to &quot;🛠️ 标准化工程落地实施 4 步法&quot;">​</a></h2><p>基于 MzMedia 的众多客户落地经验，我们总结了快速、低风险上线 AIoT 系统的标准化四步法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ┌───────────────────────┐      ┌───────────────────────┐</span></span>
<span class="line"><span> │ 阶段一：现场勘测与拓扑规划 │ ───► │ 阶段二：协议接入与物模型建模 │</span></span>
<span class="line"><span> │ · 点位布设与硬件 BoM 清单 │      │ · Modbus 寄存器与字节序校验 │</span></span>
<span class="line"><span> │ · 网络 VLAN 与带宽时延测算 │      │ · GB28181 国标通道与预置位录入│</span></span>
<span class="line"><span> └───────────────────────┘      └───────────────────────┘</span></span>
<span class="line"><span>                                                │</span></span>
<span class="line"><span>                                                ▼</span></span>
<span class="line"><span> ┌───────────────────────┐      ┌───────────────────────┐</span></span>
<span class="line"><span> │ 阶段四：运营自愈与闭环进化 │ ◄─── │ 阶段三：TCA 规则与 AI 联调   │</span></span>
<span class="line"><span> │ · MES 工单全流程流转跟踪   │      │ · 越限阈值与动作链配置       │</span></span>
<span class="line"><span> │ · 时序 RAG 维保知识库更新  │      │ · Spring AI 提示词与视觉微调 │</span></span>
<span class="line"><span> └───────────────────────┘      └───────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><ol><li><strong>阶段一：现场勘测与拓扑规划</strong><ul><li>梳理现场传感器、仪表、PLC、网络摄像机的物理布线走向；</li><li>划分网络网段（工控网 VLAN 与安防监控网 VLAN），根据视频路数规划核心交换机背板带宽（每路 4K H.265 按 4~6 Mbps 预留）。</li></ul></li><li><strong>阶段二：协议接入与物模型统一建模</strong><ul><li>登录 MzMedia 控制台，基于产品模版建立统一物模型（TSL）；</li><li>使用在线工具校验 Modbus 点位大端/小端字节序（ABCD / CDAB），配置 GB28181 SIP 接入鉴权密码并完成摄像机通道自动目录发现。</li></ul></li><li><strong>阶段三：TCA 规则与 Spring AI 智能体联调</strong><ul><li>配置 Trigger（属性上报/状态跳变）与 Condition（多条件与生效时段）；</li><li>绑定 Action（下发预置位 0x81、开始云端录像、触发反控继电器）；</li><li>挂载 Spring AI 多模态视觉复核模型或时序 RAG 工具链，过滤物理误报。</li></ul></li><li><strong>阶段四：业务协同闭环与持续进化</strong><ul><li>打通协同矩阵：对接企业微信/钉钉 Webhook 告警机器人，打通 MES 维保派工单与 WMS 备件虚拟锁定；</li><li>持续将设备原厂维保手册注入 Spring AI 知识库，使系统自愈与排障决策日益精准。</li></ul></li></ol><hr><h2 id="💻-生产环境软硬件选型与部署规格建议" tabindex="-1">💻 生产环境软硬件选型与部署规格建议 <a class="header-anchor" href="#💻-生产环境软硬件选型与部署规格建议" aria-label="Permalink to &quot;💻 生产环境软硬件选型与部署规格建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">接入规模</th><th style="text-align:left;">传感器点位</th><th style="text-align:left;">视频接入路数</th><th style="text-align:left;">推荐服务器硬件规格</th><th style="text-align:left;">架构拓扑部署形式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>基础体验级</strong></td><td style="text-align:left;">&lt; 200 点</td><td style="text-align:left;">1 ~ 8 路</td><td style="text-align:left;">4 核 CPU / 8GB 内存 / 500GB SSD</td><td style="text-align:left;">单机 Docker Compose 容器化快速启动</td></tr><tr><td style="text-align:left;"><strong>标准工业级</strong></td><td style="text-align:left;">200 ~ 2,000 点</td><td style="text-align:left;">8 ~ 32 路</td><td style="text-align:left;">8 核 CPU / 16GB 内存 / 2TB NVMe SSD</td><td style="text-align:left;">单物理机运行 MzMedia 底座 + TDengine + ZLMediaKit</td></tr><tr><td style="text-align:left;"><strong>企业高可用级</strong></td><td style="text-align:left;">2,000 ~ 20,000 点</td><td style="text-align:left;">32 ~ 128 路</td><td style="text-align:left;">2台 16核 / 32GB 内存集群 + 10Gbps 网卡</td><td style="text-align:left;">MzMedia 双机热备 + EMQX 分布式集群 + ZLMediaKit 负载均衡 + MinIO 集中存储</td></tr><tr><td style="text-align:left;"><strong>大型园区综合体</strong></td><td style="text-align:left;">&gt; 20,000 点</td><td style="text-align:left;">&gt; 128 路</td><td style="text-align:left;">K8s 容器编排集群 + 独立流媒体节点群</td><td style="text-align:left;">分布式微服务架构 + TDengine 时序高可用多副本 + 边缘计算盒子卸载 AI 推理</td></tr></tbody></table><hr><h2 id="💡-选择场景深入了解" tabindex="-1">💡 选择场景深入了解 <a class="header-anchor" href="#💡-选择场景深入了解" aria-label="Permalink to &quot;💡 选择场景深入了解&quot;">​</a></h2><p>点击下方卡片，查看详尽的场景痛点、硬件选型清单、物模型定义、规则引擎配置及实战核心源码：</p><div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:16px;margin-top:24px;"><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>📹 <a href="/cases/video-linkage">视频与传感器联动</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 消灭“只报警告警看不到现场”的盲人摸象痛点。传感器超限 1.8 秒内驱动球机预置位旋转、自动录像切片与大屏置顶。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看视频联动完整落地方案 → </div></div><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>🏭 <a href="/cases/industrial">工业应用与预测性维护</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 数控机床与旋转机械 Modbus 振动温升监控，TDengine 高频入库，Spring AI RAG 诊断磨损，自动预占 WMS 备件并派发 MES 工单。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看工业应用完整落地方案 → </div></div><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>🛡️ <a href="/cases/security">智能安防与周界防范</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 周界脉冲围栏与 4K 红外夜视球机联动，YOLO 边缘视觉识别人形攀爬并过滤误报，毫秒级反控高音爆闪声光警号。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看智能安防完整落地方案 → </div></div><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>🌱 <a href="/cases/agriculture">智慧农业与温室自愈</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 高标准连栋大棚温湿度/水肥 EC/光照闭环调控，自动启闭天窗湿帘；AI 巡航识别草莓/番茄叶片早期病斑。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看智慧农业完整落地方案 → </div></div><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>🎓 <a href="/cases/education">数字化教育与实验室安全</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 危化品防爆柜 VOC 气体 7×24h 监测，门禁联动球机视觉抓拍着装规范；课表联动智能微断空开，下课自动断电防隐患。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看数字化教育完整落地方案 → </div></div><div style="border:1px solid var(--vp-c-border);border-radius:8px;padding:18px;background:var(--vp-c-bg-soft);"><h3>⚡ <a href="/cases/energy-carbon">智慧能源与低碳建筑</a></h3><p style="font-size:13px;color:var(--vp-c-text-2);margin-top:8px;"> 工商业储能结合分时电价削峰填谷，变压器需量动态防越限，多联机中央空调柔性自适应节电，全流程节能降碳。 </p><div style="margin-top:12px;font-size:12px;font-weight:bold;color:var(--vp-c-brand-1);"> 查看智慧能源完整落地方案 → </div></div></div>`,22)])])}const f=e(r,[["render",i]]);export{b as __pageData,f as default};
